/* common.mdsr.updateMasterMdSrSrCmsDetailPop */
	UPDATE KEPASRDT A
	   SET A.DF_DATE = TO_DATE (TO_CHAR (SYSDATE, 'YYYYMMDDHH24MISS'), 'YYYYMMDDHH24MISS'),
	       A.DF_REMARK = #{st_df_remark},
	       A.FF_ATTKEY = #{st_ff_image_key},
	       A.RECV_FLAG = #{st_recv_flag},
	       A.REQ_TYPE = #{st_req_type},
	       A.REQ_SR_TYPE = #{st_req_sr_type}
	 WHERE A.USER_ID = #{st_sr_user_id} AND A.SR_NO = #{st_sr_no}


		/* common.mdsr.historyUpdateKEPASRDT */
			UPDATE KEPASRDT SET
			   SR_FLAG='Y',
			   SR_DATE=TO_DATE(TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS'), 'YYYYMMDDHH24MISS')
			WHERE USER_ID=#{st_sr_user_id}    
               AND SR_NO=#{st_sr_no}
